 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8">
     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Support Contact Form</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0d1117;
         --panel: #161b22;
         --panel-strong: #1f2937;
         --text: #f0f6fc;
         --muted: #b7c3d0;
         --border: #3d4654;
         --accent: #58a6ff;
         --accent-strong: #2f81f7;
         --error: #ff8a8a;
         --success: #8ef0a0;
         --shadow: 0 24px 80px rgb(0 0 0 / 45%);
       }

       * {
         box-sizing: border-box;
       }

       body {
         min-width: 320px;
         margin: 0;
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         line-height: 1.5;
         color: var(--text);
         background:
           radial-gradient(circle at 20% 10%, rgb(88 166 255 / 18%), transparent 28rem),
           radial-gradient(circle at 80% 0%, rgb(171 123 255 / 14%), transparent 24rem),
           var(--bg);
       }

       .skip-link {
         position: absolute;
         top: 1rem;
         left: 1rem;
         z-index: 1;
         transform: translateY(-200%);
         padding: 0.75rem 1rem;
         color: #08111f;
         background: #ffffff;
         border-radius: 0.5rem;
         font-weight: 700;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       main {
         display: grid;
         place-items: center;
         min-height: 100vh;
         padding: 2rem 1rem;
       }

       .card {
         width: min(100%, 42rem);
         padding: clamp(1.25rem, 5vw, 3rem);
         background: linear-gradient(145deg, rgb(22 27 34 / 96%), rgb(15 23 42 / 96%));
         border: 1px solid rgb(255 255 255 / 10%);
         border-radius: 1.5rem;
         box-shadow: var(--shadow);
       }

       h1 {
         margin: 0 0 0.5rem;
         font-size: clamp(2rem, 7vw, 3.6rem);
         line-height: 1.05;
         letter-spacing: -0.04em;
       }

       .intro,
       .required-note,
       .field-help {
         color: var(--muted);
       }

       .intro {
         max-width: 34rem;
         margin: 0 0 2rem;
         font-size: 1.06rem;
       }

       .required-note {
         margin: 0 0 1.5rem;
         font-size: 0.95rem;
       }

       form {
         display: grid;
         gap: 1.2rem;
       }

       .form-field {
         display: grid;
         gap: 0.45rem;
       }

       label {
         color: var(--text);
         font-weight: 700;
       }

       .required-marker {
         color: #ffb4b4;
       }

       input {
         width: 100%;
         min-height: 3.25rem;
         padding: 0.85rem 1rem;
         color: var(--text);
         background: var(--panel-strong);
         border: 1px solid var(--border);
         border-radius: 0.85rem;
         font: inherit;
         transition:
           border-color 160ms ease,
           box-shadow 160ms ease,
           background-color 160ms ease;
       }

       input:hover {
         border-color: #6e7681;
       }

       input:focus-visible,
       button:focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: 3px;
       }

       input[aria-invalid="true"] {
         border-color: var(--error);
         box-shadow: 0 0 0 1px var(--error);
       }

       .field-help,
       .form-error {
         margin: 0;
         font-size: 0.95rem;
       }

       .form-error {
         color: var(--error);
         font-weight: 700;
       }

       .actions {
         display: grid;
         gap: 1rem;
         margin-top: 0.35rem;
       }

       button {
         min-height: 3.25rem;
         padding: 0.9rem 1.4rem;
         color: #07101e;
         background: linear-gradient(135deg, #79c0ff, var(--accent-strong));
         border: 0;
         border-radius: 999px;
         font: inherit;
         font-weight: 800;
         cursor: pointer;
         box-shadow: 0 14px 30px rgb(47 129 247 / 30%);
       }

       button:hover {
         filter: brightness(1.08);
       }

       .status {
         min-height: 1.5rem;
         margin: 0;
         color: var(--success);
         font-weight: 700;
       }

       @media (max-width: 28rem) {
         main {
           padding-inline: 0.75rem;
         }

         .card {
           border-radius: 1rem;
         }
       }

       @media (forced-colors: active) {
         .card,
         input,
         button {
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         button {
           color: ButtonText;
           background: ButtonFace;
         }

         .required-marker,
         .form-error,
         .status {
           color: CanvasText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>

     <main id="main-content">
       <section class="card" aria-labelledby="support-title">
         <h1 id="support-title">Contact support</h1>
         <p class="intro">
           Tell us how to reach you and our support team will follow up as soon as possible.
         </p>

         <form id="support-form" novalidate>
           <p class="required-note" id="required-note">
             Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
           </p>

           <div class="form-field">
             <label for="full-name">
               Full name <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="full-name"
               name="full-name"
               type="text"
               autocomplete="name"
               required
               aria-describedby="required-note full-name-error"
             >
             <p class="form-error" id="full-name-error" hidden></p>
           </div>

           <div class="form-field">
             <label for="email">
               Email address <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               inputmode="email"
               required
               aria-describedby="required-note email-error"
