 <html lang="en">
   <head>
     <meta charset="utf-8">
     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Support Contact Form</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0d1117;
         --panel: #161b22;
         --panel-strong: #1f2937;
         --text: #f0f6fc;
         --muted: #b7c3d0;
         --border: #3d4654;
         --accent: #58a6ff;
         --accent-strong: #2f81f7;
